<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue';
import {History,X,RefreshCw,Search,ArrowUpRight,ShieldCheck} from 'lucide-vue-next';
import {api} from './api';
const props=defineProps<{courseId:number;userId:number;role:string}>();const emit=defineEmits(['changed','open-submission']);
const dialog=ref<HTMLDialogElement>(),detail=ref<any>(null),records=ref<any[]>([]),mode=ref('records'),action=ref('APPROVE'),reason=ref(''),visibility=ref('COURSE'),shareFeedback=ref(false),q=ref(''),state=ref(''),page=ref(1),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),conflict=ref(false);let generation=0,alive=true,returnFocus:HTMLElement|null=null;
// 「发布记录」按钮只挂在阅读页的 #publication-entry 上；社区页没有这个节点，Teleport 找不到目标会让整个弹窗停止更新。
const hasEntry=!!document.getElementById('publication-entry');
const teacher=computed(()=>props.role==='TEACHER');const names:Record<string,string>={PENDING:'待审核',PUBLISHED:'已发布',RETURNED:'已退回',WITHDRAWN:'已撤回'};const actions:Record<string,string>={REQUEST:'申请发布',APPROVE:'审核通过',RETURN:'退回修改',CANCEL:'撤回申请',TEACHER_WITHDRAW:'教师撤回展示',AUTHOR_WITHDRAW:'作者撤回展示',REGRADE:'复评自动撤回'};
const filtered=computed(()=>records.value.filter(r=>(!state.value||r.state===state.value)&&`${r.title} ${r.author_name} ${r.assignment_title}`.toLocaleLowerCase().includes(q.value.trim().toLocaleLowerCase())));const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/20)));const shown=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20));
const allowed=computed(()=>{const d=detail.value;if(!d)return false;if(action.value==='REQUEST')return d.author_id===props.userId&&(!d.id||['WITHDRAWN','RETURNED'].includes(d.state));if(['APPROVE','RETURN'].includes(action.value))return teacher.value&&d.state==='PENDING';return action.value==='WITHDRAW'&&(teacher.value||d.author_id===props.userId)&&['PENDING','PUBLISHED'].includes(d.state);});
const mayDecide=computed(()=>detail.value&&(teacher.value||detail.value.author_id===props.userId));
function fmt(s:string){return s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—';}
async function present(){returnFocus=document.activeElement as HTMLElement;error.value='';message.value='';reason.value='';conflict.value=false;await nextTick();if(!dialog.value?.open)dialog.value?.showModal();}
async function load(){const g=++generation;loading.value=true;error.value='';try{const r=await api(`/courses/${props.courseId}/publication-records`);if(alive&&g===generation)records.value=r;}catch(e:any){if(g===generation)error.value=e.message;}finally{if(g===generation)loading.value=false;}}
async function list(){mode.value='records';detail.value=null;await present();await load();}
async function fetchDetail(id:number){const g=++generation;loading.value=true;error.value='';try{const d=await api(`/publications/${id}/review`);if(alive&&g===generation){detail.value=d;visibility.value=d.visibility==='PUBLIC'?'PUBLIC':'COURSE';shareFeedback.value=!!d.share_feedback;conflict.value=false;}}catch(e:any){if(g===generation){error.value=e.message;conflict.value=true;detail.value=null;}}finally{if(g===generation)loading.value=false;}}
async function open(id:number,a=''){mode.value='detail';action.value=a;detail.value=null;await present();await fetchDetail(id);}
async function request(sid:number,p:any,title:string){visibility.value='COURSE';shareFeedback.value=false;if(p){await open(p.id,'REQUEST');return;}mode.value='detail';action.value='REQUEST';await present();detail.value={submission_id:sid,title,author_id:props.userId,revision:0,events:[]};}
function close(){if(busy.value)return;if(reason.value.trim()&&!confirm('离开将放弃尚未提交的发布理由，是否继续？'))return;generation++;dialog.value?.close();reason.value='';detail.value=null;returnFocus?.focus();}
async function refresh(){if(detail.value?.id){await fetchDetail(detail.value.id);message.value='状态已刷新，输入的理由仍保留；请重新核对后提交。';}else await load();}
async function submit(){if(!detail.value||!allowed.value||busy.value||conflict.value||loading.value)return;const d=detail.value;busy.value=true;error.value='';try{if(action.value==='REQUEST')await api(`/submissions/${d.submission_id}/publication-request`,'POST',{revision:d.revision,reason:reason.value,visibility:visibility.value,shareFeedback:shareFeedback.value});else await api(`/publications/${d.id}/decisions`,'POST',{action:action.value,revision:d.revision,reason:reason.value});reason.value='';action.value='';message.value='发布处理已保存。指定提交版本不变，操作历史已保留。';if(d.id)await fetchDetail(d.id);else {await load();const p=records.value.find(x=>x.submission_id===d.submission_id);if(p)await fetchDetail(p.id);}if(alive)emit('changed');}catch(e:any){error.value=e.message;if([409,403,422].includes(e.status))conflict.value=true;}finally{busy.value=false;}}
function read(sid:number){close();if(!dialog.value?.open)emit('open-submission',sid);}
function unload(e:BeforeUnloadEvent){if(reason.value.trim()||busy.value){e.preventDefault();e.returnValue='';}}
watch([q,state],()=>page.value=1);watch(()=>[props.courseId,props.userId,props.role],()=>{generation++;reason.value='';records.value=[];detail.value=null;dialog.value?.close();});window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{alive=false;generation++;window.removeEventListener('beforeunload',unload);});defineExpose({open,request});
</script>
<template><Teleport v-if="hasEntry" to="#publication-entry"><button class="btn secondary" @click="list"><History :size="16"/>{{ teacher?'发布审核与记录':'我的发布记录' }}</button></Teleport>
<dialog ref="dialog" class="publication-dialog" aria-labelledby="pub-title" @cancel.prevent="close"><header><div><span class="eyebrow">课程知识共建 · 指定版本发布</span><h2 id="pub-title">{{ mode==='records'?(teacher?'发布审核与记录':'我的发布记录'):'发布审核详情' }}</h2></div><button class="icon-btn" aria-label="关闭发布详情" :disabled="busy" @click="close"><X :size="20"/></button></header>
<div class="publication-body"><p class="muted"><ShieldCheck :size="15"/>默认仅在本课程展示；作者可在申请时选择全站公开。审核理由与操作记录仅作者和任课教师可见。后续草稿不会替换已发布版本。</p><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="message" class="alert" role="status">{{ message }}</p><p v-if="loading" role="status">正在读取发布记录…</p>
<template v-if="mode==='records'"><div class="filter-row"><label class="search-box"><Search :size="16"/><input v-model="q" aria-label="搜索发布记录" placeholder="标题、作者或作业" maxlength="80"/></label><select v-model="state" aria-label="发布记录状态"><option value="">全部状态</option><option v-for="(n,s) in names" :value="s" :key="s">{{ n }}</option></select><button class="btn secondary" :disabled="loading" @click="load"><RefreshCw :size="15"/>刷新记录</button></div><article v-for="r in shown" :key="r.id" class="publication-record"><div><strong>{{ r.title }}</strong><p class="muted">{{ r.author_name }} · v{{ r.version_no }} · {{ r.assignment_title }}</p><small class="muted">申请于 {{ fmt(r.requested_at) }}</small></div><span class="badge" :class="r.state==='PUBLISHED'?'green':r.state==='PENDING'?'orange':''">{{ names[r.state] }}</span><button class="btn secondary" @click="open(r.id)">查看发布详情</button></article><p v-if="!loading&&!filtered.length" class="empty-text">没有匹配的发布记录。先获得教师正式评价，再申请发布。</p><div class="publication-pagination"><span class="muted">{{ filtered.length }} 条记录 · 第 {{ page }}/{{ pages }} 页</span><button class="btn secondary" :disabled="page<=1" @click="page--">上一页</button><button class="btn secondary" :disabled="page>=pages" @click="page++">下一页</button></div></template>
<template v-else-if="detail"><div class="publication-detail-heading"><div><h3>{{ detail.title }}</h3><p class="muted">{{ detail.author_name }} <template v-if="detail.version_no">· v{{ detail.version_no }}</template> · {{ names[detail.state]||'尚未申请' }}</p></div><button class="text-btn" @click="read(detail.submission_id)">阅读指定版本<ArrowUpRight :size="15"/></button></div>
<div v-if="detail.last_reason" class="publication-reason"><strong>最近处理理由</strong><p>{{ detail.last_reason }}</p></div>
<div v-if="mayDecide" class="button-row"><template v-if="detail.state==='PENDING'&&teacher"><button class="btn secondary" @click="action='APPROVE'">审核通过</button><button class="btn secondary" @click="action='RETURN'">退回修改</button></template><button v-if="['PENDING','PUBLISHED'].includes(detail.state)" class="btn secondary" @click="action='WITHDRAW'">{{ detail.state==='PENDING'?'撤回发布申请':'撤回社区展示' }}</button><button v-if="detail.author_id===userId&&['RETURNED','WITHDRAWN'].includes(detail.state)" class="btn secondary" @click="action='REQUEST'">重新申请发布</button><button v-if="detail.id" class="text-btn" :disabled="busy||loading" @click="refresh"><RefreshCw :size="15"/>刷新当前状态</button></div>
<form v-if="action" class="publication-form" @submit.prevent="submit"><h3>{{ action==='REQUEST'?'申请发布':action==='RETURN'?'退回修改':action==='APPROVE'?'同意发布':'撤回此版本' }}</h3><p v-if="action==='RETURN'||action==='WITHDRAW'" class="muted">{{ action==='RETURN'?'请说明需要补充或修改什么。作者可按此理由修订，也可为此提交版重新申请。':'撤回后同学无法继续访问此版本。' }}</p><fieldset v-if="action==='REQUEST'" class="visibility-choice"><legend>可见范围</legend><label><input type="radio" value="COURSE" v-model="visibility"/> 仅本课程同学可见</label><label><input type="radio" value="PUBLIC" v-model="visibility"/> 全站公开（其他课程的同学也能读到，需你本人同意）</label><p class="muted">可以随时在发布记录里撤回；撤回后该版本不再对外展示。</p></fieldset><fieldset v-if="action==='REQUEST'" class="visibility-choice"><legend>批注公开</legend><label><input type="checkbox" v-model="shareFeedback"/> 公开教师批注作为范例</label><p class="muted">默认不公开：批注是对这一版说的修改意见，只对作者和教师可见。勾选后，同学能在这一版的修订历史里看到老师当时标了什么、为什么这么改；你对批注的回应不会公开。</p></fieldset><label for="publication-reason">{{ action==='REQUEST'?'申请说明（选填）':'处理理由（必填）' }}</label><textarea id="publication-reason" v-model="reason" :required="action!=='REQUEST'" maxlength="2000" rows="4" :disabled="busy" placeholder="写下本次处理依据，便于作者与教师后续核对"/><p v-if="!allowed" class="muted">当前状态不再允许此操作，请核对上方状态并选择可用操作。</p><p v-if="conflict" class="muted">输入已保留，请刷新状态后重试。</p><button class="btn primary" :disabled="!allowed||busy||loading||conflict||(action!=='REQUEST'&&!reason.trim())">{{ busy?'正在保存…':'确认发布处理' }}</button></form>
<h3 class="publication-history-title">操作历史 <span class="badge">{{ detail.events.length }} 条</span></h3><article v-for="h in detail.events" :key="h.id" class="publication-history"><strong>{{ actions[h.action_type]||h.action_type }}</strong><span class="muted">{{ h.actor_name }} · {{ h.actor_role==='TEACHER'?'教师':'作者' }} · {{ fmt(h.created_at) }}</span><p>{{ h.reason }}</p><small class="muted">{{ h.before_state==='NEW'?'未申请':names[h.before_state] }} → {{ names[h.after_state] }}<template v-if="h.evaluation_revision"> · 评价 r{{ h.evaluation_revision }}</template></small></article><p v-if="!detail.events.length" class="muted">暂无操作历史；历史版本升级前的审核过程不会补造。</p></template></div>
<footer><button class="btn secondary" :disabled="busy" @click="close">关闭发布记录</button></footer></dialog></template>
<style scoped>
.publication-dialog{width:min(820px,calc(100vw - 48px));max-height:88vh;padding:0;border:1px solid var(--border);border-radius:14px;background:var(--paper);color:var(--text)}.publication-dialog::backdrop{background:#11182766}.publication-dialog header,.publication-dialog footer{padding:20px 26px;display:flex;justify-content:space-between;align-items:center;background:var(--paper);border-bottom:1px solid var(--border)}.publication-dialog footer{border-top:1px solid var(--border);border-bottom:0;justify-content:flex-end}.publication-body{padding:22px 26px;overflow:auto;max-height:65vh}.publication-body>p:first-child{font-size:13px}.publication-record{display:flex;gap:14px;align-items:center;padding:20px 0;border-bottom:1px solid var(--border)}.publication-record>div{flex:1;min-width:0;overflow-wrap:anywhere}.publication-record p{margin:5px 0}.publication-pagination{display:flex;align-items:center;gap:10px;margin-top:18px}.publication-pagination>span{flex:1}.publication-form{margin:20px 0;padding:20px;background:var(--surface);border:1px solid var(--border);border-radius:10px}.publication-form label{display:block;margin:12px 0 6px}.publication-form textarea{width:100%;resize:vertical;min-height:100px}.publication-form .btn{margin-top:14px}.publication-detail-heading{display:flex;justify-content:space-between;gap:18px;margin:18px 0}.publication-reason{background:var(--surface);padding:16px;border-radius:8px;margin:18px 0;white-space:pre-wrap;overflow-wrap:anywhere}.publication-history-title{margin-top:26px}.publication-history{border-bottom:1px solid var(--border);padding:16px 0;overflow-wrap:anywhere}.publication-history>span{display:block;font-size:12px;margin-top:4px}.publication-history p{white-space:pre-wrap;margin:8px 0}.filter-row{margin:20px 0}.filter-row .search-box{flex:1;min-width:150px}select,textarea{color:var(--text);background:var(--paper);border:1px solid var(--border);border-radius:6px;padding:9px}.alert{padding:12px;background:var(--blue-soft);border-radius:7px}.alert.error{background:var(--red-soft);color:var(--red)}
</style>
